create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());`nalter table public.profiles enable row level security;`ncreate policy profiles_self_read on public.profiles for select using (id = auth.uid());`ncreate policy profiles_self_update on public.profiles for update using (id = auth.uid()) with check (id = auth.uid());